height = data['map']['Height']
wrap_x = data['map']['WrapX']

grid = {}
for p in data['plots']:
    pid = p['ID']
    x = pid % width
    y = pid // width
    grid[(x, y)] = {
        'id': pid,
        'terrain': p['TerrainType'],
        'features': [],
        'x': x, 'y': y
    }

for f in data['features'].values():
    pid = f['ID']
    x = pid % width
    y = pid // width
    if (x, y) in grid:
