        if w_neighbor in grid: grid[w_neighbor]['has_river'] = True
    if river_edges.get((x,y,'NW')):
        nw_nx = x - 1 + offset
        nw_ny = y + 1
        nw_neighbor = (nw_nx%width, nw_ny) if wrap_x else (nw_nx, nw_ny)
        if nw_neighbor in grid: grid[nw_neighbor]['has_river'] = True
    if river_edges.get((x,y,'NE')):
        ne_nx = x + offset
        ne_ny = y + 1
        ne_neighbor = (ne_nx%width, ne_ny) if wrap_x else (ne_nx, ne_ny)
        if ne_neighbor in grid: grid[ne_neighbor]['has_river'] = True

def get_neighbors(x, y):
    offset = y % 2
    candidates = [
        (x - 1, y),
        (x + 1, y),
        (x - 1 + offset, y - 1),
        (x + offset, y - 1),
        (x - 1 + offset, y + 1),
        (x + offset, y + 1)
    ]
    valid = []
    for nx, ny in candidates:
        if wrap_x:
            nx = nx % width
        if 0 <= nx < width and 0 <= ny < height:
            valid.append((nx, ny))
    return valid

def is_mountain(node):
    return 'MOUNTAIN' in node['terrain']

def is_coast(node):
    return node['terrain'] == 'TERRAIN_COAST'

def is_water(node):
    return node['terrain'] in ['TERRAIN_COAST', 'TERRAIN_OCEAN']

def is_valid_land(node):
    return not is_water(node) and not is_mountain(node) and 'ICE' not in node['features']

def calc_campus(node, neighbors, dist_neighbors):
    score = 0
    score += sum(1 for n in neighbors if is_mountain(grid[n]))
    score += sum(1 for n in neighbors if 'FEATURE_JUNGLE' in grid[n]['features']) // 2
    score += sum(2 for n in neighbors if 'FEATURE_REEF' in grid[n]['features'])
    score += sum(2 for n in neighbors if 'FEATURE_GEOTHERMAL_FISSURE' in grid[n]['features'])
    score += dist_neighbors // 2
    return score

def calc_holy_site(node, neighbors, dist_neighbors):
    score = 0
    score += sum(1 for n in neighbors if is_mountain(grid[n]))
    score += sum(1 for n in neighbors if 'FEATURE_FOREST' in grid[n]['features']) // 2
    score += dist_neighbors // 2
    return score

def calc_commercial_hub(node, neighbors, dist_neighbors):
    score = 0
    if node.get('has_river'):
        score += 2
    score += dist_neighbors // 2
    return score

def calc_theater_square(node, neighbors, dist_neighbors):
    score = 0
    score += sum(1 for n in neighbors if 'FEATURE_JUNGLE' in grid[n]['features']) // 2
    score += dist_neighbors // 2
    return score

def calc_harbor(node, neighbors, dist_neighbors):
    score = 0
    score += dist_neighbors // 2
    return score

city_candidates = []
for coord, node in grid.items():
    if is_valid_land(node):
        city_candidates.append(coord)

def get_dist_score(dtype, coord, placed_districts, cc_coord):
    neighbors = get_neighbors(coord[0], coord[1])
    dist_neighbors = 0
    for n in neighbors:
        if n in placed_districts or n == cc_coord:
            dist_neighbors += 1
    node = grid[coord]
    score = 0
    if dtype == 'CAMPUS':
        score = calc_campus(node, neighbors, dist_neighbors)
    elif dtype == 'HOLY_SITE':
        score = calc_holy_site(node, neighbors, dist_neighbors)
    elif dtype == 'COMMERCIAL_HUB':
        score = calc_commercial_hub(node, neighbors, dist_neighbors)
        # +2 from Harbor (Major Adjacency)
        for n in neighbors:
            if placed_districts.get(n) == 'HARBOR':
                score += 2
    elif dtype == 'THEATER_SQUARE':
        score = calc_theater_square(node, neighbors, dist_neighbors)
    elif dtype == 'HARBOR':
        score = calc_harbor(node, neighbors, dist_neighbors)
        if cc_coord in neighbors:
            score += 2
    return score

intrinsic_scores = {}
for coord, node in grid.items():
    neighbors = get_neighbors(*coord)
    scores = {}
    scores['CAMPUS'] = calc_campus(node, neighbors, 0)
    scores['HOLY_SITE'] = calc_holy_site(node, neighbors, 0)
    scores['COMMERCIAL_HUB'] = 2 if node.get('has_river') else 0
    scores['THEATER_SQUARE'] = calc_theater_square(node, neighbors, 0)
    scores['HARBOR'] = 0
    intrinsic_scores[coord] = scores

candidate_priority = []
for cc in city_candidates:
    score = 0
    neighbors = get_neighbors(*cc)
    for n in neighbors:
        if n in intrinsic_scores:
             score += max(intrinsic_scores[n].values())
    candidate_priority.append((score, cc))
candidate_priority.sort(key=lambda x: x[0], reverse=True)

best_total = -1
best_solution = None

for _, cc in candidate_priority[:50]:
    n1 = get_neighbors(*cc)
    valid_spots = []
    for n in n1:
        if n not in valid_spots: valid_spots.append(n)
    for n in n1:
        for n2 in get_neighbors(*n):
            if n2 != cc and n2 not in valid_spots: valid_spots.append(n2)

    land_spots = [p for p in valid_spots if is_valid_land(grid[p])]
    coast_spots = [p for p in valid_spots if is_coast(grid[p])]

    top_land = sorted(land_spots, key=lambda p: max(intrinsic_scores[p].values()), reverse=True)[:6]
    top_coast = coast_spots[:3]
    pool = top_land + top_coast
    if len(pool) < 3: continue

    import itertools
    for spot_combo in itertools.combinations(pool, 3):
        spot_types = []
        for spot in spot_combo:
            if is_coast(grid[spot]): spot_types.append(['HARBOR'])
            else: spot_types.append(['CAMPUS', 'HOLY_SITE', 'COMMERCIAL_HUB', 'THEATER_SQUARE'])

        for types in itertools.product(*spot_types):
            placements = {}
            for i in range(3):
                placements[spot_combo[i]] = types[i]
            if len(set(types)) != 3: continue

            current_adj = 0
            bonuses = {}
            for spot, dtype in placements.items():
                score = get_dist_score(dtype, spot, placements, cc)
                bonuses[dtype] = score
                current_adj += score

            if current_adj > best_total:
                best_total = current_adj
                best_solution = {
                    "city_center": list(cc),
                    "placements": {k: list(v) for v, k in placements.items()},
                    "adjacency_bonuses": bonuses,
                    "total_adjacency": current_adj
                }

print(json.dumps(best_solution, indent=2))
EOF
